-- ============================================================
-- pg-xerp data-layer port: frmGoodsInward   (posts)
-- Dialect = pg's OWN proven fast-grid (sp_brand_grid2 = 88ms/100k)
-- + xErp's sp_<formid>_<verb> naming so crud.js resolves them.
-- Table created here; procs match the form's grafted form.json.
-- ============================================================
CREATE TABLE IF NOT EXISTS public."tblfrmGoodsInward" (
    "Id"        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "from_" text NOT NULL DEFAULT '',
    "to_" text NOT NULL DEFAULT '',
    "challanno" text NOT NULL DEFAULT '',
    "FCODE"     text NOT NULL DEFAULT '',
    "User_Id"   text NOT NULL DEFAULT '',
    "Lock"      smallint NOT NULL DEFAULT 0,
    "LOCK_User_Id" text NOT NULL DEFAULT '',
    "Created_At" timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_Grid2(
    p_pagesize integer, p_pageno integer, p_search text,
    p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("Id" bigint, "Detail" text, "rc" bigint)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT t."Id", t.det, count(*) OVER() AS rc
    FROM (
        SELECT r."Id",
               json_build_object('from_', r."from_", 'to_', r."to_", 'challanno', r."challanno")::text AS det
        FROM public."tblfrmGoodsInward" r
        WHERE (p_search = '' OR r."from_" ILIKE '%' || p_search || '%' OR r."to_" ILIKE '%' || p_search || '%' OR r."challanno" ILIKE '%' || p_search || '%')
        ORDER BY r."Id" DESC
        LIMIT p_pagesize OFFSET (p_pageno - 1) * p_pagesize
    ) t;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_GridCount1(
    p_search text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("rc" bigint) LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY SELECT count(*)::bigint FROM public."tblfrmGoodsInward";
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_DFE1(
    p_id bigint, p_formid text, p_auth text, p_fcode text)
RETURNS TABLE("Id" bigint, "Detail" text)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT r."Id", json_build_object('from_', r."from_", 'to_', r."to_", 'challanno', r."challanno")::text
    FROM public."tblfrmGoodsInward" r
    WHERE r."Id" = p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_SAVE(
    p_from text, p_to text, p_challanno text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text, "id" bigint)
LANGUAGE plpgsql AS $function$
DECLARE v_id bigint;
BEGIN
    INSERT INTO public."tblfrmGoodsInward" ("from_", "to_", "challanno")
    VALUES (p_from, p_to, p_challanno)
    RETURNING "Id" INTO v_id;
    RETURN QUERY SELECT 'Success'::text, ''::text, v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_UPDATE(
    p_id bigint, p_from text, p_to text, p_challanno text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmGoodsInward" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    UPDATE public."tblfrmGoodsInward" SET "from_" = p_from, "to_" = p_to, "challanno" = p_challanno WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_Delete1(
    p_id bigint, p_formid text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmGoodsInward" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    DELETE FROM public."tblfrmGoodsInward" WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmGoodsInward_LockUnlock1(
    p_formid text, p_auth text, p_company text, p_id bigint)
RETURNS TABLE("status" text, "message" text) LANGUAGE plpgsql AS $function$
BEGIN
    UPDATE public."tblfrmGoodsInward" SET "Lock" = CASE WHEN "Lock" = 0 THEN 1 ELSE 0 END
    WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;
